// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait ImageAvailabilityControl_acquisition_process_image_availability_control_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control)
  }

  /** helper function to set the values of all input ports.
   * @param request_facts payload for data port request_facts
   * @param batch_facts payload for data port batch_facts
   * @param image_result_facts payload for data port image_result_facts
   * @param recovery_frame payload for data port recovery_frame
   */
  def put_concrete_inputs(request_facts : EIT_Acquisition_Supervisor.RequestFactsRecord,
                          batch_facts : EIT_Acquisition_Supervisor.BatchFacts.Type,
                          image_result_facts : EIT_Acquisition_Supervisor.ImageResultFacts.Type,
                          recovery_frame : EIT_Acquisition_Supervisor.RecoveryFrame): Unit = {
    put_request_facts(request_facts)
    put_batch_facts(batch_facts)
    put_image_result_facts(image_result_facts)
    put_recovery_frame(recovery_frame)
  }


  /** helper function to check ImageAvailabilityControl_acquisition_process_image_availability_control's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param image_frame method that will be called with the value of the outgoing data
   *        port 'image_frame'.
   */
  def check_concrete_output(image_frame: EIT_Acquisition_Supervisor.ImageFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val image_frameValue: EIT_Acquisition_Supervisor.ImageFrame = get_image_frame().get
    if(!image_frame(image_frameValue)) {
      testFailures = testFailures :+ st"'image_frame' did not match expected: value of the outgoing data port is ${image_frameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_request_facts(value : EIT_Acquisition_Supervisor.RequestFactsRecord): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control.operational_api.request_facts_Id, EIT_Acquisition_Supervisor.RequestFactsRecord_Payload(value))
  }

  // setter for in DataPort
  def put_batch_facts(value : EIT_Acquisition_Supervisor.BatchFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control.operational_api.batch_facts_Id, EIT_Acquisition_Supervisor.BatchFacts_Payload(value))
  }

  // setter for in DataPort
  def put_image_result_facts(value : EIT_Acquisition_Supervisor.ImageResultFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control.operational_api.image_result_facts_Id, EIT_Acquisition_Supervisor.ImageResultFacts_Payload(value))
  }

  // setter for in DataPort
  def put_recovery_frame(value : EIT_Acquisition_Supervisor.RecoveryFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control.operational_api.recovery_frame_Id, EIT_Acquisition_Supervisor.RecoveryFrame_Payload(value))
  }

  // getter for out DataPort
  def get_image_frame(): Option[EIT_Acquisition_Supervisor.ImageFrame] = {
    val value: Option[EIT_Acquisition_Supervisor.ImageFrame] = get_image_frame_payload() match {
      case Some(EIT_Acquisition_Supervisor.ImageFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port image_frame.  Expecting 'EIT_Acquisition_Supervisor.ImageFrame_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.ImageFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_image_frame_payload(): Option[EIT_Acquisition_Supervisor.ImageFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control.initialization_api.image_frame_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.ImageFrame_Payload]]
  }

}
